/**
 * A visitor's bitmaps (RFC-020 §5.1). The art is drawn as detailed SVG, part
 * by part (public/festivals/<art>/<part>.svg, generated by
 * webapp/scripts/festival-art/<id>.py), and each part is rasterised once to
 * an ImageBitmap at the screen's pixel ratio, capped at 1.5 as the weather's
 * canvas is. A frame then only moves, rotates and layers those bitmaps: a
 * few dozen drawImage calls whatever the detail.
 *
 * The bitmaps are made in idle time when a festival with a visitor starts
 * and closed when it ends (releaseVisitorSprites), never for a festival that
 * isn't on.
 */

import type { FestivalId } from "@/lib/festivals";
import type { VisitorSpec } from "./types";

export type Bitmap = ImageBitmap | HTMLCanvasElement;

export interface VisitorSprites {
  festival: FestivalId;
  /** The size the parts were drawn for: art units to CSS pixels. */
  scale: number;
  parts: Record<string, Bitmap>;
  /** Presents (three colours) and a star, for the tap. */
  presents: Bitmap[];
  star: Bitmap;
  /** Fireworks: a soft spark per colour, drawn once. */
  sparks: Bitmap[];
  /** How long rasterising took, ms: reported by the benchmark (§7.1). */
  ms: number;
}

/** A canvas as a bitmap where the browser can, else the canvas itself. */
async function toBitmap(c: HTMLCanvasElement): Promise<Bitmap> {
  if (typeof createImageBitmap === "function") {
    try {
      const bitmap = await createImageBitmap(c);
      c.width = 0;
      c.height = 0;
      return bitmap;
    } catch {
      // Older WebKit: draw from the canvas.
    }
  }
  return c;
}

function canvas(w: number, h: number): [HTMLCanvasElement, CanvasRenderingContext2D | null] {
  const c = document.createElement("canvas");
  c.width = Math.max(1, Math.ceil(w));
  c.height = Math.max(1, Math.ceil(h));
  return [c, c.getContext("2d")];
}

/** One part's SVG, drawn at `k` device pixels per art unit. */
async function rasterisePart(art: string, name: string, w: number, h: number, k: number): Promise<Bitmap> {
  const img = new Image();
  img.decoding = "async";
  img.src = `/festivals/${art}/${name}.svg`;
  await img.decode();
  const [c, ctx] = canvas(w * k, h * k);
  ctx?.drawImage(img, 0, 0, c.width, c.height);
  return toBitmap(c);
}

/** A wrapped present, lit from the top left like the rest of the art. */
async function presentSprite(k: number, box: string, ribbon: string): Promise<Bitmap> {
  const s = 34;
  const [c, ctx] = canvas(s * k, s * k);
  if (ctx) {
    ctx.scale(k, k);
    ctx.translate(s / 2, s / 2 + 3);
    const body = ctx.createLinearGradient(-14, -12, 14, 14);
    body.addColorStop(0, box);
    body.addColorStop(1, "rgba(0, 0, 0, 0.25)");
    ctx.fillStyle = box;
    ctx.beginPath();
    ctx.roundRect(-13, -11, 26, 23, 3.5);
    ctx.fill();
    ctx.fillStyle = body;
    ctx.globalAlpha = 0.45;
    ctx.fill();
    ctx.globalAlpha = 1;
    ctx.fillStyle = ribbon;
    ctx.fillRect(-2.5, -11, 5, 23);
    ctx.fillRect(-13, -2.5, 26, 5);
    // The bow.
    ctx.beginPath();
    ctx.moveTo(0, -11);
    ctx.quadraticCurveTo(-11, -22, -13, -14);
    ctx.quadraticCurveTo(-8, -10, 0, -11);
    ctx.quadraticCurveTo(11, -22, 13, -14);
    ctx.quadraticCurveTo(8, -10, 0, -11);
    ctx.fill();
    ctx.fillStyle = "rgba(255, 255, 255, 0.35)";
    ctx.fillRect(-11, -9, 6, 4);
  }
  return toBitmap(c);
}

/** A four-pointed sparkle with a soft glow, drawn into the sprite (canvas blur is slow on a Pi). */
async function starSprite(k: number): Promise<Bitmap> {
  const s = 30;
  const [c, ctx] = canvas(s * k, s * k);
  if (ctx) {
    ctx.scale(k, k);
    ctx.translate(s / 2, s / 2);
    const glow = ctx.createRadialGradient(0, 0, 0, 0, 0, 14);
    glow.addColorStop(0, "rgba(255, 226, 122, 0.85)");
    glow.addColorStop(0.5, "rgba(255, 226, 122, 0.25)");
    glow.addColorStop(1, "rgba(255, 226, 122, 0)");
    ctx.fillStyle = glow;
    ctx.fillRect(-15, -15, 30, 30);
    ctx.fillStyle = "#FFE27A";
    ctx.beginPath();
    for (let i = 0; i < 8; i++) {
      const a = (i * Math.PI) / 4 - Math.PI / 2;
      const r = i % 2 === 0 ? 10 : 3;
      if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
      else ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
    }
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = "#FFFFFF";
    ctx.beginPath();
    ctx.arc(0, 0, 2.2, 0, Math.PI * 2);
    ctx.fill();
  }
  return toBitmap(c);
}

/**
 * A firework's spark: a white-hot core in a glow of its colour, 16 CSS px
 * across at `dpr`. Drawn once per colour, so a burst of a hundred sparks is a
 * hundred drawImage calls, no gradients per frame.
 */
async function sparkSprite(dpr: number, color: string): Promise<Bitmap> {
  const s = 16;
  const [c, ctx] = canvas(s * dpr, s * dpr);
  if (ctx) {
    ctx.scale(dpr, dpr);
    const g = ctx.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);
    g.addColorStop(0, "rgba(255, 255, 255, 1)");
    g.addColorStop(0.18, color);
    g.addColorStop(0.45, color);
    g.addColorStop(1, "rgba(0, 0, 0, 0)");
    ctx.fillStyle = g;
    ctx.globalAlpha = 0.95;
    ctx.fillRect(0, 0, s, s);
  }
  return toBitmap(c);
}

const cache = new Map<string, Promise<VisitorSprites>>();
/** A number per visitor spec: a kit with a visitor per stage (Lunar New Year) has two sets of bitmaps. */
const specIds = new WeakMap<VisitorSpec, number>();
let nextSpecId = 0;

/**
 * Every bitmap of a festival's visitor, drawn once for this size and pixel
 * ratio; shared by Home and the screensaver.
 */
export function prepareVisitorSprites(festival: FestivalId, spec: VisitorSpec, scale: number, dpr: number): Promise<VisitorSprites> {
  if (!specIds.has(spec)) specIds.set(spec, nextSpecId++);
  const key = `${festival}|${scale.toFixed(3)}|${dpr}|${specIds.get(spec)}`;
  let ready = cache.get(key);
  if (!ready) {
    ready = (async () => {
      const started = performance.now();
      const k = scale * dpr;
      const art = spec.art ?? festival;
      const specs = spec.parts ?? {};
      const names = Object.keys(specs);
      const bitmaps = await Promise.all(names.map((n) => rasterisePart(art, n, specs[n].w, specs[n].h, k)));
      const presents = spec.tap && spec.tap.presents
        ? await Promise.all([
            presentSprite(k * 1.6, "#E04848", "#FFD24A"),
            presentSprite(k * 1.6, "#4AA8FF", "#FFD24A"),
            presentSprite(k * 1.6, "#3FA877", "#F4EBDD"),
          ])
        : [];
      const star = await starSprite(k * 1.6);
      const sparks = spec.archetype === "fireworks" ? await Promise.all(spec.colors.map((c) => sparkSprite(dpr, c))) : [];
      return {
        festival,
        scale,
        parts: Object.fromEntries(names.map((n, i) => [n, bitmaps[i]])),
        presents,
        star,
        sparks,
        ms: performance.now() - started,
      };
    })();
    // A failed load (offline, a missing file) is tried again next time.
    ready.catch(() => cache.delete(key));
    cache.set(key, ready);
  }
  return ready;
}

/** Close the bitmaps (the festival is over, or the screen changed size): a megabyte or two given back. */
export function releaseVisitorSprites(keep?: (festival: FestivalId, scale: number) => boolean): void {
  for (const [key, ready] of cache) {
    const [festival, scale] = key.split("|");
    if (keep?.(festival as FestivalId, Number(scale))) continue;
    cache.delete(key);
    void ready
      .then((s) => {
        for (const b of [...Object.values(s.parts), ...s.presents, s.star, ...s.sparks]) if ("close" in b) b.close();
      })
      .catch(() => undefined);
  }
}
